tool_input.command:
cd D:\repository\skills
for($i=1;$i -le 3;$i++){
  Write-Output "=== attempt $i ==="
  git push origin main 2>&1
  if($LASTEXITCODE -eq 0){ Write-Output "PUSH OK on attempt $i"; break }
  Start-Sleep -Seconds 4
}
Write-Output "=== final status ==="; git status -sb | Select-Object -First 1

Write-Output "=== proxy env ==="; $env:HTTP_PROXY; $env:HTTPS_PROXY
Write-Output "=== git proxy config ==="; git -C D:\repository\skills config --get http.proxy; git -C D:\repository\skills config --get https.proxy
Write-Output "=== test github 443 ==="; try{ (Test-NetConnection github.com -Port 443 -WarningAction SilentlyContinue).TcpTestSucceeded }catch{ "err $_" }
Write-Output "=== test general internet (magpie local not counted) ==="; try{ (Invoke-WebRequest "https://www.baidu.com" -TimeoutSec 8 -UseBasicParsing).StatusCode }catch{ "baidu err: $($_.Exception.Message)" }
